=<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            margin: 0;
            padding: 20px;
            background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            min-height: 100vh;
        }

        .email-container {
            width: 100%;
            max-width: 800px;
            margin: 0 auto;
            background: white;
            border-radius: 20px;
            overflow: hidden;
            box-shadow: 0 20px 50px rgba(0, 0, 0, 0.5);
        }

        /* HEADER */
        .header {
            background: linear-gradient(90deg, #d32f2f 0%, #b71c1c 100%);
            padding: 30px;
            text-align: center;
        }

        .header h1 {
            color: white;
            font-size: 32px;
            font-weight: 700;
            margin: 0;
        }

        /* MAIN CONTENT */
        .main-content {
            padding: 40px;
            text-align: center;
        }

        /* VITAL SIGNS */
        .vital-signs {
            display: flex;
            justify-content: center;
            gap: 40px;
            margin-bottom: 40px;
            flex-wrap: wrap;
        }

        .vital-card {
            background: #f5f5f5;
            border-radius: 15px;
            padding: 25px;
            min-width: 180px;
            box-shadow: 0 5px 15px rgba(0,0,0,0.1);
        }

        .vital-icon {
            font-size: 40px;
            margin-bottom: 15px;
            display: block;
        }

        .vital-label {
            color: #666;
            font-size: 16px;
            font-weight: 600;
            margin-bottom: 10px;
        }

        .vital-value {
            font-size: 42px;
            font-weight: 800;
            color: #d32f2f;
        }

        .time-value {
            color: #1976d2;
            font-size: 36px;
        }

        /* AI VERDICT - CENTER PIECE */
        .ai-verdict-container {
            background: linear-gradient(135deg, #fff3e0 0%, #ffecb3 100%);
            border-radius: 20px;
            padding: 50px;
            margin: 40px 0;
            border: 3px solid #ff9800;
            text-align: center;
        }

        .verdict-header {
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 15px;
            margin-bottom: 30px;
        }

        .verdict-icon {
            font-size: 48px;
        }

        .verdict-title {
            color: #e65100;
            font-size: 36px;
            font-weight: 800;
            margin: 0;
        }

        .verdict-text {
            color: #5d4037;
            font-size: 24px;
            line-height: 1.8;
            margin: 0;
            padding: 20px;
            background: rgba(255, 255, 255, 0.9);
            border-radius: 15px;
            border-left: 5px solid #ff9800;
            min-height: 200px;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        /* FOOTER */
        .footer {
            background: #333;
            padding: 30px;
            text-align: center;
            color: white;
        }

        .date-display {
            font-size: 18px;
            color: #bbbbbb;
            margin-bottom: 20px;
        }

        .creator {
            color: #4fc3f7;
            font-size: 24px;
            font-weight: 700;
            margin: 20px 0;
        }

        .disclaimer {
            color: #aaaaaa;
            font-size: 12px;
            line-height: 1.5;
            margin-top: 20px;
            font-style: italic;
        }

        /* RESPONSIVE */
        @media (max-width: 600px) {
            .vital-signs {
                flex-direction: column;
                align-items: center;
            }

            .vital-card {
                width: 100%;
                max-width: 300px;
            }

            .ai-verdict-container {
                padding: 30px 20px;
            }

            .verdict-title {
                font-size: 28px;
            }

            .verdict-text {
                font-size: 20px;
                padding: 15px;
            }
        }
    </style>
</head>
<body>
    <div class="email-container">
        <!-- HEADER -->
        <div class="header">
            <h1>⚕️ AI CARDIAC DIAGNOSTIC REPORT</h1>
        </div>

        <!-- MAIN CONTENT -->
        <div class="main-content">
            <!-- VITAL SIGNS -->
            <div class="vital-signs">
                <div class="vital-card">
                    <span class="vital-icon">❤️</span>
                    <div class="vital-label">HEART RATE</div>
                    <div class="vital-value">{{ $('Webhook2').item.json.body.bpm }} BPM</div>
                </div>

                <div class="vital-card">
                    <span class="vital-icon">🕒</span>
                    <div class="vital-label">MEASURED AT</div>
                    <div class="vital-value time-value">{{ $('DATE').item.json.localTime }}</div>
                </div>
            </div>

            <!-- AI VERDICT - CENTER FOCUS -->
            <div class="ai-verdict-container">
                <div class="verdict-header">
                    <span class="verdict-icon">🤖</span>
                    <h2 class="verdict-title">AI DIAGNOSTIC VERDICT</h2>
                </div>

                <div class="verdict-text">
                    {{ $json.output }}
                </div>
            </div>
        </div>

        <!-- FOOTER -->
        <div class="footer">
            <div class="date-display">{{ $now.format("MMMM DD, YYYY") }}</div>

            <div class="creator">CREATED BY : AMADEUS RAMOS</div>

            <div class="disclaimer">
                ⚕️ This report is AI-generated for informational purposes only. 
                Always consult with a healthcare professional for medical advice.
            </div>
        </div>
    </div>
</body>
</html>
